import{_ as t,o,c as n,ax as a}from"./chunks/framework.Bnt0oLax.js";const m=JSON.parse('{"title":"SDK Concepts","description":"Why these docs use the word SDK for three different things — two constructed libraries (Widget SDK, Web SDK) and one runtime context object — and how they relate","frontmatter":{"description":"Why these docs use the word SDK for three different things — two constructed libraries (Widget SDK, Web SDK) and one runtime context object — and how they relate"},"headers":[],"relativePath":"sdk/concepts.md","filePath":"sdk/concepts.md"}'),r={name:"sdk/concepts.md"};function s(d,e,i,c,h,l){return o(),n("div",null,[...e[0]||(e[0]=[a('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/sdk/concepts.md for this page in Markdown format</div><h1 id="sdk-concepts" tabindex="-1">SDK Concepts <a class="header-anchor" href="#sdk-concepts" aria-label="Permalink to &quot;SDK Concepts&quot;">​</a></h1><p>The word &quot;SDK&quot; shows up in three places in these docs, but only two of them are actually SDKs. This page explains what each one is, why they&#39;re kept separate, and which page to go to for each.</p><h2 id="two-sdks-and-one-runtime-context-object" tabindex="-1">Two SDKs and one runtime context object <a class="header-anchor" href="#two-sdks-and-one-runtime-context-object" aria-label="Permalink to &quot;Two SDKs and one runtime context object&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>What it is</th><th>How you access it</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><strong><a href="/docs/sdk/widget-sdk/overview.html">Widget SDK</a></strong></td><td>A JavaScript class you construct</td><td><code>new window.WidgetServiceSDK()</code>, called from inside your widget code</td><td>Call <a href="/docs/connectors/">Connectors</a> to reach external APIs without exposing credentials in the browser</td></tr><tr><td><strong><a href="/docs/sdk/web-sdk/overview.html">Web SDK</a></strong></td><td>A global object already on the page</td><td><code>ChWebSdk</code> — bundled with the community frontend, no construction needed</td><td>Search content, manage users and subscriptions, and interact with the DOM on community pages</td></tr><tr><td><strong><a href="/docs/custom-widgets/v2/core-concepts.html">Widget Runtime</a></strong> (the <code>sdk</code> parameter)</td><td>A context object, not a library</td><td>Passed automatically as the argument to your widget&#39;s <code>init(sdk)</code> function — see the <a href="/docs/custom-widgets/v2/sdk-api-reference.html">Widget Runtime Reference</a></td><td>Gives your widget its shadow root, current props, and design tokens</td></tr></tbody></table><p>The first two are libraries you call, the same way you&#39;d call any client SDK: you construct or reference an instance, then invoke methods on it. The third is not — it&#39;s an interface the platform hands you, the same way React hands a component its <code>props</code> or Express hands a handler <code>req</code>/<code>res</code>. Nothing about it is optional or constructed; it already exists by the time your <code>init</code> function runs.</p><h2 id="why-they-re-kept-separate" tabindex="-1">Why they&#39;re kept separate <a class="header-anchor" href="#why-they-re-kept-separate" aria-label="Permalink to &quot;Why they&#39;re kept separate&quot;">​</a></h2><p>Each one talks to a different layer, so collapsing them would mix unrelated concerns:</p><ul><li><strong>Widget SDK</strong> is a backend proxy client. Calling an external API directly from the browser would expose your credentials, so this SDK exists purely to route requests through the platform instead.</li><li><strong>Web SDK</strong> is a community-platform client. It has nothing to do with external APIs — it searches and manages content that already lives in the community itself.</li><li><strong>Widget Runtime</strong> isn&#39;t a client for anything external. It&#39;s the contract between the platform and your widget&#39;s lifecycle: where to render, what configuration you were given, and what to do when that configuration changes.</li></ul><p>A widget can use all three at once — read its props from the runtime object, call a connector through the Widget SDK, and search community content through the Web SDK — without any of the three needing to know the others exist.</p><h2 id="common-confusion" tabindex="-1">Common confusion <a class="header-anchor" href="#common-confusion" aria-label="Permalink to &quot;Common confusion&quot;">​</a></h2><p>The runtime object and the Widget SDK are easy to mix up because widget code often names both of them <code>sdk</code>. The runtime object has no <code>.connectors</code> property, so calling <code>sdk.connectors.execute(...)</code> inside <code>init(sdk)</code> throws <code>Cannot read properties of undefined (reading &#39;execute&#39;)</code>. See <a href="/docs/connectors/calling-from-widgets.html">Calling from Widget Code</a> for how to construct a separate, distinctly-named Widget SDK instance instead.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next&quot;">​</a></h2><ul><li><a href="/docs/custom-widgets/v2/build-first-widget.html">Your First Widget</a> — build a widget hands-on and see the <code>init(sdk)</code> parameter in action</li><li><a href="/docs/sdk/widget-sdk/overview.html">Widget SDK</a> — call connectors from widget code</li><li><a href="/docs/sdk/web-sdk/overview.html">Web SDK</a> — search, users, and subscriptions on community pages</li><li><a href="/docs/custom-widgets/v2/sdk-api-reference.html">Widget Runtime Reference</a> — full API for the <code>init(sdk)</code> parameter</li></ul>',14)])])}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
